using System.ComponentModel.DataAnnotations;
namespace Staybnb.Models;
public class Property { public int Id {get;set;} [Required,StringLength(120)] public string Title {get;set;}=""; [Required,StringLength(3000)] public string Description {get;set;}=""; [Range(1,1000000)] public decimal PricePerNight {get;set;} [Range(0,100000)] public decimal CleaningFee {get;set;}=0; [Range(0,100000)] public decimal ServiceFee {get;set;}=0; [Required,StringLength(150)] public string Address {get;set;}=""; [Required,StringLength(80)] public string City {get;set;}=""; [StringLength(60)] public string PropertyType {get;set;}="Apartment"; [Range(1,30)] public int MaxGuests {get;set;}=2; public bool IsActive {get;set;}=false; [Required] public string HostId {get;set;}=""; public ApplicationUser? Host {get;set;} public DateTime CreatedAt {get;set;}=DateTime.UtcNow; public List<PropertyImage> Images {get;set;}=[]; public List<Booking> Bookings {get;set;}=[]; }